        const [el, setEl] = createSignal(null, { ownedWrite: true });
        for (let k = 0; k < refEffects; k++) createEffect(() => el(), () => {});
        setEl({ i });
        return visible;
      }),
    );
    createRenderEffect(() => rows().length, () => {});
    flush();
    const t0 = performance.now();
    setItems(Array.from({ length: N }, (_, i) => i));
    flush();
    ms = performance.now() - t0;
  });
  dispose();
